const body = $json;
if (!body.legal_entity_id) throw new Error('Missing legal_entity_id');
if (!body.attendees?.length) throw new Error('Missing attendees');
const slots = [];
const start = new Date(body.date_range.start_date);
for (let i=0; i<5; i++) {
  const slot = new Date(start.getTime() + i * 60 * 60 * 1000);
  slot.setHours(9 + i, 0, 0, 0);
  slots.push({start: slot.toISOString(), end: new Date(slot.getTime() + body.duration_minutes*60000).toISOString(), score: 100 - i});
}
return [{json: {slots}}];
